    """Raised when ``render`` is asked for a format that is not registered."""


def register(name: str) -> Callable[[Renderer], Renderer]:
    """Decorator registering ``func`` as the renderer for format ``name``."""

    def decorator(func: Renderer) -> Renderer:
        _REGISTRY[name] = func
        return func

    return decorator


def available_formats() -> list[str]:
    return sorted(_REGISTRY)


def render(report: dict, fmt: str) -> str:
    try:
        renderer = _REGISTRY[fmt]
    except KeyError:
        raise UnknownFormat(
            f"unknown format {fmt!r}; available: {', '.join(available_formats())}"
        ) from None
    return renderer(_normalize(report))


def render_many(reports: Iterable[dict], fmt: str) -> list[str]:
    """Render each report in ``reports`` with format ``fmt``, in order."""
    return [render(report, fmt) for report in reports]


# --- shared helpers -------------------------------------------------------


def _normalize(report: dict) -> dict:
    """Return a copy of ``report`` with every cell converted to ``str``."""
    return {
        "title": str(report.get("title", "")),
        "columns": _cells(report.get("columns", [])),
        "rows": [_cells(row) for row in report.get("rows", [])],
    }


def _cells(values: Iterable[object]) -> list[str]:
    return [str(v) for v in values]


def _pipe_row(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def _html_row(cells: list[str], tag: str) -> str:
    inner = "".join(f"<{tag}>{html.escape(c)}</{tag}>" for c in cells)
    return f"<tr>{inner}</tr>"


# --- renderers ------------------------------------------------------------


@register("text")
def render_text(report: dict) -> str:
    body = "\n".join("  ".join(row) for row in report["rows"])
    return f"{report['title']}\n\n{body}"


@register("markdown")
def render_markdown(report: dict) -> str:
    columns = report["columns"]
    lines = [f"# {report['title']}", "", _pipe_row(columns)]
    lines.append("|" + "---|" * len(columns))
    lines.extend(_pipe_row(row) for row in report["rows"])
    return "\n".join(lines)


@register("csv")
def render_csv(report: dict) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(report["columns"])
    writer.writerows(report["rows"])
    return buf.getvalue().rstrip("\n")


