def render_html(report: dict) -> str:
    lines = [
        f"<h1>{html.escape(report['title'])}</h1>",
        "<table>",
        _html_row(report["columns"], "th"),
    ]
    lines.extend(_html_row(row, "td") for row in report["rows"])
    lines.append("</table>")
    return "\n".join(lines)
